@import url('https://fonts.googleapis.com/css2?family=Ma+Shan+Zheng&family=Noto+Serif+SC:wght@500;600&display=swap');
/* 橘子汽水 · Orange Soda —— 素材全部外链，不内嵌图片、不加脚本、不加动画 */
:root{
 --os-paper:#fbf1df; --os-ink:#4a3a2c; --os-ink2:#7a6450; --os-mute:#a08a72;
 --os-orange:#ef8a3c; --os-orange2:#f6a04d; --os-mint:#a9c9a4; --os-mint2:#dfeedd; --os-line:#e2cfb3;
 --os-serif:"Noto Serif SC","Source Han Serif SC","Songti SC","STSong",serif;
 --os-brush:"Ma Shan Zheng","STKaiti","KaiTi",var(--os-serif);
 --os-u:1px;
 --os-head:calc(var(--os-u)*106);
 --topBarBlockSize:calc(var(--os-u)*172);
 --mes-right-spacing:0px;
}

/* ---------- 画布：奶油纸 + 左侧橙子树 ---------- */
#sheld{background:var(--os-paper) url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/orange-soda-v2/paper.webp') 0 0/calc(var(--os-u)*256) repeat!important;box-shadow:none!important;backdrop-filter:none!important;transform:none!important;filter:none!important;contain:none!important;will-change:auto!important}
#sheld::after{
 content:"";position:absolute;left:calc(var(--os-u)*-18);top:calc(var(--os-u)*4);width:calc(var(--os-u)*80);height:calc(var(--os-u)*242);
 background:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/orange-soda-v2/tree-edge.webp') left top/100% auto no-repeat;opacity:.9;pointer-events:none;z-index:-1;
}
#chat{
 position:relative;z-index:auto!important;background:transparent!important;backdrop-filter:none!important;-webkit-backdrop-filter:none!important;text-shadow:none!important;
 transform:none!important;filter:none!important;contain:none!important;will-change:auto!important;
 padding:calc(var(--os-u)*10) calc(var(--os-u)*8) calc(var(--os-u)*10)!important;gap:0!important;
 --mes-right-spacing:0px!important;
}
#form_sheld{position:relative;z-index:2}

/* ---------- 顶部固定资料区：画在 #sheld 里，最新一条角色消息的头像、名字、数字固定上去 ---------- */
#sheld::before{
 content:"";position:fixed;left:0;top:0;width:100vw;height:var(--topBarBlockSize);z-index:20;pointer-events:none;
 background:
  url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/orange-soda-v2/bottle.webp') right calc(var(--os-u)*-2) top calc(var(--os-u)*-2)/calc(var(--os-u)*128) auto no-repeat,
  url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/orange-soda-v2/leaf-corner.webp') left calc(var(--os-u)*-26) top calc(var(--os-u)*-22)/calc(var(--os-u)*96) auto no-repeat,
  linear-gradient(transparent calc(var(--os-head) - 1px),#dcc6a6 calc(var(--os-head) - 1px),#dcc6a6 var(--os-head),transparent var(--os-head)),
  var(--os-paper) url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/orange-soda-v2/paper.webp') 0 0/calc(var(--os-u)*256) repeat;
 border-bottom:1px dashed #d9c3a4;box-shadow:0 2px 8px rgba(120,80,30,.08);
}
#top-bar#top-bar{background:transparent!important;background-color:transparent!important;border:0!important;box-shadow:none!important;backdrop-filter:none!important;pointer-events:none!important;height:var(--topBarBlockSize)!important}
#top-settings-holder{height:var(--topBarBlockSize)!important;align-items:flex-start!important;padding:calc(var(--os-head) + var(--os-u)*7) calc(var(--os-u)*2) 0!important;box-sizing:border-box!important;pointer-events:none!important}
#top-settings-holder>.drawer{pointer-events:auto}
#top-settings-holder>.drawer{min-width:0!important}
#top-settings-holder .drawer-toggle{display:flex!important;flex-direction:column!important;align-items:center!important;gap:calc(var(--os-u)*2)}
#top-settings-holder .drawer-icon{
 display:block!important;width:calc(var(--os-u)*36)!important;height:calc(var(--os-u)*36)!important;padding:0!important;
 font-size:0!important;color:transparent!important;opacity:1!important;filter:none!important;
 background:var(--os-ico) center/contain no-repeat!important;
}
#top-settings-holder .drawer-icon.closedIcon{opacity:.92!important}
#top-settings-holder .drawer-icon.openIcon{filter:drop-shadow(0 0 calc(var(--os-u)*3) rgba(239,138,60,.65))!important}
#top-settings-holder .drawer-icon::before{content:none!important}
#top-settings-holder .drawer-toggle::after{
 font:600 calc(var(--os-u)*10)/1 var(--os-serif);color:var(--os-ink2);letter-spacing:.06em;white-space:nowrap;
}
#ai-config-button{--os-ico:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/orange-soda-v2/icon-notebook.webp')}#ai-config-button .drawer-toggle::after{content:"预设"}
#sys-settings-button{--os-ico:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/orange-soda-v2/icon-chat.webp')}#sys-settings-button .drawer-toggle::after{content:"连接"}
#advanced-formatting-button{--os-ico:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/orange-soda-v2/icon-folder.webp')}#advanced-formatting-button .drawer-toggle::after{content:"格式"}
#WI-SP-button{--os-ico:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/orange-soda-v2/icon-book.webp')}#WI-SP-button .drawer-toggle::after{content:"世界书"}
#user-settings-button{--os-ico:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/orange-soda-v2/icon-gear.webp')}#user-settings-button .drawer-toggle::after{content:"设置"}
#backgrounds-button{--os-ico:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/orange-soda-v2/icon-home.webp')}#backgrounds-button .drawer-toggle::after{content:"背景"}
#extensions-settings-button{--os-ico:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/orange-soda-v2/icon-grid.webp')}#extensions-settings-button .drawer-toggle::after{content:"扩展"}
#persona-management-button{--os-ico:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/orange-soda-v2/icon-person.webp')}#persona-management-button .drawer-toggle::after{content:"人设"}
#rightNavHolder{--os-ico:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/orange-soda-v2/icon-compass.webp')}#rightNavHolder .drawer-toggle::after{content:"角色"}

/* ---------- 每条消息的通用结构 ---------- */
#chat .mes,#chat .mes *{text-shadow:none!important}
#chat .mes{
 position:relative;display:block!important;flex:none!important;box-sizing:border-box;width:100%!important;max-width:none!important;
 margin:0!important;padding:0 0 calc(var(--os-u)*34)!important;border:0!important;border-radius:0!important;
 background:transparent!important;box-shadow:none!important;color:var(--os-ink);font-family:var(--os-serif);
}
#chat .mes>.for_checkbox,#chat .mes>.del_checkbox{position:absolute}
#chat .mes .ch_name{display:contents!important}
#chat .mes .mes_ghost{color:var(--os-mute)}
/* 消息之间：点线 + 橙子片 */
#chat .mes::after{
 content:"";position:absolute;left:calc(var(--os-u)*30);right:calc(var(--os-u)*30);bottom:calc(var(--os-u)*8);height:calc(var(--os-u)*20);pointer-events:none;
 background:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/orange-soda-v2/sticker-orange.webp') center/auto 100% no-repeat,radial-gradient(circle,#d8b98f 1.2px,transparent 1.6px) 0 50%/calc(var(--os-u)*9) calc(var(--os-u)*9) repeat-x;
 -webkit-mask:linear-gradient(90deg,#000 0 calc(50% - var(--os-u)*22),transparent 0 calc(50% + var(--os-u)*22),#000 0);mask:none;
}
#chat .mes.last_mes::after{display:none}

/* 正文 */
#chat .mes .mes_text{
 margin:0!important;padding:0!important;width:auto!important;max-width:100%!important;min-width:0;
 font:500 calc(var(--os-u)*16)/1.85 var(--os-serif);letter-spacing:.03em;color:var(--os-ink);overflow-wrap:anywhere;
}
#chat .mes .mes_text p{margin:0 0 .75em;text-align:justify;text-justify:inter-character;text-align-last:start}
#chat .mes .mes_text p:last-child{margin-bottom:0}
#chat .mes .mes_text :is(q,blockquote){color:#9a5420}
#chat .mes .mes_text :is(em,i){color:var(--os-ink2)}

/* ---------- 角色消息：卡片里的小抬头（头像、名字、三个数字、时间） ---------- */
#chat .mes[is_user="false"]{padding-top:calc(var(--os-u)*4)!important}
#chat .mes[is_user="false"]>.mesAvatarWrapper{
 position:absolute!important;left:calc(var(--os-u)*78);top:calc(var(--os-u)*26);z-index:3;
 display:block!important;width:calc(var(--os-u)*38)!important;height:calc(var(--os-u)*38)!important;margin:0!important;padding:0!important;
}
#chat .mes[is_user="false"]>.mesAvatarWrapper>.avatar{
 width:100%!important;height:100%!important;margin:0!important;padding:0!important;border-radius:50%!important;box-shadow:none!important;overflow:visible!important;
}
#chat .mes[is_user="false"]>.mesAvatarWrapper>.avatar img{width:100%!important;height:100%!important;border-radius:50%!important;border:0!important;box-shadow:0 0 0 calc(var(--os-u)*2) #fff8ec,0 0 0 calc(var(--os-u)*3) #e8d2b0!important}
#chat .mes[is_user="false"] :is(.mesIDDisplay,.mes_timer,.tokenCounterDisplay){
 position:absolute!important;top:calc(var(--os-u)*22);margin:0!important;padding:0!important;opacity:1!important;white-space:nowrap;
 font:600 calc(var(--os-u)*10.5)/1.3 var(--os-serif)!important;color:var(--os-mute)!important;text-align:left!important;
}
#chat .mes[is_user="false"] .mesIDDisplay{left:calc(var(--os-u)*48)}
#chat .mes[is_user="false"] .mes_timer{left:calc(var(--os-u)*78)}
#chat .mes[is_user="false"] .tokenCounterDisplay{left:calc(var(--os-u)*130)}
#chat .mes[is_user="false"] :is(.mes_timer,.tokenCounterDisplay):empty{display:none}
#chat .mes[is_user="false"] .ch_name>.flex1{
 grid-column:2;grid-row:1;display:flex!important;align-items:flex-start;min-height:calc(var(--os-u)*44);padding-left:calc(var(--os-u)*48);
 margin-bottom:calc(var(--os-u)*6);border-bottom:1px dashed rgba(170,130,80,.28);
}
#chat .mes[is_user="false"] .ch_name>.flex1>div{display:flex!important;align-items:baseline!important;width:100%;gap:calc(var(--os-u)*8)}
#chat .mes[is_user="false"] .name_text{font:600 calc(var(--os-u)*15)/1.3 var(--os-serif)!important;color:#3a2c20!important;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;min-width:0}
#chat .mes[is_user="false"] .timestamp{margin-left:auto;font:600 calc(var(--os-u)*10.5)/1.3 var(--os-serif)!important;color:var(--os-mute);white-space:nowrap}

/* ---------- 最新一条角色消息：头像、名字、数字固定到最上面的资料区 ---------- */
#chat>.mes[is_user="false"]:not([is_system="true"]):not(:has(~.mes[is_user="false"]:not([is_system="true"])))>.mesAvatarWrapper{
 position:fixed!important;left:0!important;top:0!important;z-index:21!important;width:100vw!important;height:var(--os-head)!important;pointer-events:none;
}
#chat>.mes[is_user="false"]:not([is_system="true"]):not(:has(~.mes[is_user="false"]:not([is_system="true"])))>.mesAvatarWrapper>.avatar{
 position:absolute!important;left:calc(var(--os-u)*24);top:calc(var(--os-u)*14);width:calc(var(--os-u)*78)!important;height:calc(var(--os-u)*78)!important;pointer-events:auto;
}
#chat>.mes[is_user="false"]:not([is_system="true"]):not(:has(~.mes[is_user="false"]:not([is_system="true"])))>.mesAvatarWrapper>.avatar img{box-shadow:0 0 0 calc(var(--os-u)*3) #fff8ec!important}
#chat>.mes[is_user="false"]:not([is_system="true"]):not(:has(~.mes[is_user="false"]:not([is_system="true"])))>.mesAvatarWrapper>.avatar::after{
 content:"";position:absolute;left:50%;top:50%;width:calc(var(--os-u)*120);height:calc(var(--os-u)*108);transform:translate(-50%,-50%);
 background:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/orange-soda-v2/avatar-garland.webp') center/100% 100% no-repeat;pointer-events:none;
}
#chat>.mes[is_user="false"]:not([is_system="true"]):not(:has(~.mes[is_user="false"]:not([is_system="true"]))) :is(.mesIDDisplay,.mes_timer,.tokenCounterDisplay){
 left:calc(var(--os-u)*214)!important;min-width:calc(var(--os-u)*60);height:calc(var(--os-u)*20);box-sizing:border-box;padding:0 calc(var(--os-u)*8)!important;
 border:1px solid #e6d3b6;border-radius:999px;background:rgba(255,250,240,.92);
 font:600 calc(var(--os-u)*11)/calc(var(--os-u)*18) var(--os-serif)!important;color:var(--os-ink2)!important;text-align:center!important;
}
#chat>.mes[is_user="false"]:not([is_system="true"]):not(:has(~.mes[is_user="false"]:not([is_system="true"]))) .mesIDDisplay{top:calc(var(--os-u)*18)!important}
#chat>.mes[is_user="false"]:not([is_system="true"]):not(:has(~.mes[is_user="false"]:not([is_system="true"]))) .mes_timer{top:calc(var(--os-u)*42)!important}
#chat>.mes[is_user="false"]:not([is_system="true"]):not(:has(~.mes[is_user="false"]:not([is_system="true"]))) .tokenCounterDisplay{top:calc(var(--os-u)*66)!important}
#chat>.mes[is_user="false"]:not([is_system="true"]):not(:has(~.mes[is_user="false"]:not([is_system="true"]))) .name_text{
 position:fixed!important;left:calc(var(--os-u)*116);top:calc(var(--os-u)*24);z-index:21;width:calc(var(--os-u)*92);
 font:400 calc(var(--os-u)*30)/1.15 var(--os-brush)!important;color:#2f2620!important;pointer-events:none;
}
#chat>.mes[is_user="false"]:not([is_system="true"]):not(:has(~.mes[is_user="false"]:not([is_system="true"]))) .name_text::after{content:"";display:block;width:80%;height:calc(var(--os-u)*4);margin-top:calc(var(--os-u)*4);border-radius:4px;background:linear-gradient(90deg,var(--os-orange),rgba(239,138,60,0))}
#chat>.mes[is_user="false"]:not([is_system="true"]):not(:has(~.mes[is_user="false"]:not([is_system="true"]))) .ch_name>.flex1{padding-left:0}

/* 角色正文卡：撕边奶油纸，左边一条邮票齿孔工具栏 */
#chat .mes[is_user="false"]>.mes_block{
 position:static!important;display:grid!important;grid-template-columns:calc(var(--os-u)*40) minmax(0,1fr);column-gap:calc(var(--os-u)*8);align-items:start;
 width:auto!important;max-width:none!important;min-width:0!important;margin:0 calc(var(--os-u)*2)!important;
 box-sizing:border-box;min-height:calc(var(--os-u)*170);
 padding:calc(var(--os-u)*8) calc(var(--os-u)*8) calc(var(--os-u)*10) calc(var(--os-u)*4)!important;
 border:calc(var(--os-u)*16) solid transparent!important;
 border-image:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/orange-soda-v2/card-cream.webp') 40 fill / calc(var(--os-u)*16) stretch!important;
 background:transparent!important;overflow:visible!important;
}
#chat .mes[is_user="false"] .mes_buttons{grid-column:1;grid-row:1 / span 9}
#chat .mes[is_user="false"] :is(.mes_edit_buttons,.mes_reasoning_details,.mes_text,.mes_media_wrapper,.mes_file_wrapper,.mes_bias){grid-column:2}
#chat .mes[is_user="false"] .mes_edit_buttons{grid-row:2}
#chat .mes[is_user="false"] .mes_text{grid-row:3}
#chat .mes[is_user="false"] .mes_reasoning_details{grid-row:4}
#chat .mes[is_user="false"] .mes_media_wrapper{grid-row:5}
#chat .mes[is_user="false"] .mes_file_wrapper{grid-row:6}
#chat .mes[is_user="false"] .mes_bias{grid-row:7}
/* 窗景：浮在正文右上，字绕着走 */
#chat .mes[is_user="false"] .mes_text::before{
 content:"";float:right;width:calc(var(--os-u)*92);height:calc(var(--os-u)*106);margin:calc(var(--os-u)*-4) calc(var(--os-u)*-6) calc(var(--os-u)*6) calc(var(--os-u)*10);
 background:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/orange-soda-v2/window.webp') center/contain no-repeat;transform:rotate(2deg);
}
/* 工具栏 */
#chat .mes[is_user="false"] .mes_buttons{
 position:relative!important;inset:auto!important;transform:none!important;align-self:start;
 display:flex!important;flex-direction:column!important;flex-wrap:nowrap!important;align-items:center!important;justify-content:flex-start!important;
 width:calc(var(--os-u)*36)!important;max-width:none!important;height:auto!important;
 gap:calc(var(--os-u)*4)!important;margin:calc(var(--os-u)*-2) 0 0!important;padding:calc(var(--os-u)*8) 0!important;box-sizing:border-box;
 border:calc(var(--os-u)*6) solid transparent!important;border-image:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/orange-soda-v2/stamp-strip.webp') 22 fill / calc(var(--os-u)*7) stretch!important;
 overflow:visible!important;transform:rotate(-1.5deg)!important;
}
#chat .mes[is_user="false"] .mes_buttons .extraMesButtons{flex-direction:column!important;flex-wrap:nowrap!important;gap:calc(var(--os-u)*4)!important;height:auto!important;overflow:visible!important;align-items:center}
/* 按钮颜色（两边通用） */
#chat .mes .mes_button,#chat .mes .extraMesButtons>div{
 font-size:calc(var(--os-u)*15)!important;color:#6f5a45!important;opacity:.85!important;filter:none!important;padding:calc(var(--os-u)*4)!important;
}

/* 思绪：薄荷绿便签 */
#chat .mes .mes_reasoning_details{margin:calc(var(--os-u)*10) 0 0!important}
#chat .mes .mes_reasoning_summary{margin:0!important}
#chat .mes .mes_reasoning_header{
 margin:0!important;padding:calc(var(--os-u)*6) calc(var(--os-u)*36) calc(var(--os-u)*6) calc(var(--os-u)*16)!important;
 background:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/orange-soda-v2/tape-green.webp') center/100% 100% no-repeat!important;border:0!important;border-radius:0!important;
 font:600 calc(var(--os-u)*12.5)/1.4 var(--os-serif)!important;color:#3f5a3c!important;width:max-content;max-width:100%;
}
#chat .mes .mes_reasoning_arrow{color:#4c6b48!important}
#chat .mes .mes_reasoning{
 box-sizing:border-box;width:calc(var(--os-u)*270);max-width:100%;height:calc(var(--os-u)*275);overflow:auto;overscroll-behavior:contain;
 margin:calc(var(--os-u)*6) 0 0!important;padding:calc(var(--os-u)*56) calc(var(--os-u)*24) calc(var(--os-u)*60) calc(var(--os-u)*34)!important;
 background:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/orange-soda-v2/notepad.webp') center/100% 100% no-repeat!important;border:0!important;
 font:500 calc(var(--os-u)*13)/1.75 var(--os-serif)!important;color:#43573f!important;
}

/* ---------- 用户消息：橙色纸卡，右侧头像，左下猫咪书堆 ---------- */
#chat .mes[is_user="true"]{padding-top:calc(var(--os-u)*14)!important;min-height:calc(var(--os-u)*120)}
#chat .mes[is_user="true"]::before{
 content:"";position:absolute;left:calc(var(--os-u)*-4);bottom:calc(var(--os-u)*26);width:calc(var(--os-u)*112);height:calc(var(--os-u)*80);
 background:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/orange-soda-v2/cat-books.webp') left bottom/contain no-repeat;pointer-events:none;z-index:0;
}
#chat .mes[is_user="true"]>.mesAvatarWrapper{
 position:absolute!important;right:calc(var(--os-u)*4);top:calc(var(--os-u)*30);z-index:3;
 display:block!important;width:calc(var(--os-u)*52)!important;height:calc(var(--os-u)*52)!important;margin:0!important;padding:0!important;
}
#chat .mes[is_user="true"]>.mesAvatarWrapper>:not(.avatar){display:none!important}
#chat .mes[is_user="true"]>.mesAvatarWrapper>.avatar{width:100%!important;height:100%!important;margin:0!important;border-radius:50%!important;box-shadow:none!important}
#chat .mes[is_user="true"]>.mesAvatarWrapper>.avatar img{width:100%!important;height:100%!important;border-radius:50%!important;border:0!important;box-shadow:0 0 0 calc(var(--os-u)*3) #fff6e8,0 calc(var(--os-u)*2) calc(var(--os-u)*6) rgba(150,90,30,.25)!important}
#chat .mes[is_user="true"]>.mes_block{
 position:relative!important;z-index:1;display:flex!important;flex-direction:column!important;
 width:auto!important;max-width:none!important;min-width:0!important;margin:0 calc(var(--os-u)*58) 0 calc(var(--os-u)*64)!important;
 padding:calc(var(--os-u)*6) calc(var(--os-u)*10) calc(var(--os-u)*8)!important;box-sizing:border-box;
 border:calc(var(--os-u)*14) solid transparent!important;
 border-image:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/orange-soda-v2/card-orange.webp') 40 fill / calc(var(--os-u)*14) stretch!important;
 background:transparent!important;overflow:visible!important;
}
/* 纸胶带和小爱心 */
#chat .mes[is_user="true"]>.mes_block::before{
 content:"";position:absolute;left:calc(var(--os-u)*-26);top:calc(var(--os-u)*-22);width:calc(var(--os-u)*62);height:calc(var(--os-u)*22);
 background:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/orange-soda-v2/tape-orange.webp') center/100% 100% no-repeat;transform:rotate(-14deg);pointer-events:none;
}
#chat .mes[is_user="true"]>.mes_block::after{
